-- ProAqua: сначала добавляем колонки для картинок (безопасно для повторного запуска)
SET @db := DATABASE();

SET @sql := (
  SELECT IF(COUNT(*)=0,
    'ALTER TABLE Services ADD COLUMN ImageData longblob NULL',
    'SELECT 1')
  FROM information_schema.COLUMNS
  WHERE TABLE_SCHEMA=@db AND TABLE_NAME='Services' AND COLUMN_NAME='ImageData');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @sql := (
  SELECT IF(COUNT(*)=0,
    'ALTER TABLE Services ADD COLUMN ImageContentType varchar(100) NULL',
    'SELECT 1')
  FROM information_schema.COLUMNS
  WHERE TABLE_SCHEMA=@db AND TABLE_NAME='Services' AND COLUMN_NAME='ImageContentType');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @sql := (
  SELECT IF(COUNT(*)=0,
    'ALTER TABLE Promotions ADD COLUMN ImageData longblob NULL',
    'SELECT 1')
  FROM information_schema.COLUMNS
  WHERE TABLE_SCHEMA=@db AND TABLE_NAME='Promotions' AND COLUMN_NAME='ImageData');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @sql := (
  SELECT IF(COUNT(*)=0,
    'ALTER TABLE Promotions ADD COLUMN ImageContentType varchar(100) NULL',
    'SELECT 1')
  FROM information_schema.COLUMNS
  WHERE TABLE_SCHEMA=@db AND TABLE_NAME='Promotions' AND COLUMN_NAME='ImageContentType');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

INSERT INTO Services (Id, Title, Description, Category, DurationMinutes, PriceFrom, ImageUrl, BeforeAfterImageUrl, IsActive, SortOrder, ImageData, ImageContentType)
VALUES ('c1111111-1111-1111-1111-111111111111', 'Экспресс-мойка', 'Кузов, диски, сушка. Быстро вернём блеск перед городом.', 'wash', 40, 800.00, NULL, NULL, 1, 1, FROM_BASE64(''), 'image/jpeg')
ON DUPLICATE KEY UPDATE
  Title=VALUES(Title), Description=VALUES(Description), Category=VALUES(Category),
  DurationMinutes=VALUES(DurationMinutes), PriceFrom=VALUES(PriceFrom), SortOrder=VALUES(SortOrder),
  ImageData=VALUES(ImageData), ImageContentType=VALUES(ImageContentType), IsActive=1;

