INSERT INTO Promotions (Id, Title, Description, StartsAt, EndsAt, IsActive, ImageUrl, ImageData, ImageContentType, CreatedAt)
VALUES ('e1111111-1111-1111-1111-111111111111', 'Комплекс со скидкой 15%', 'При записи на комплексную мойку в будни — скидка 15%.', UTC_TIMESTAMP(6), DATE_ADD(UTC_TIMESTAMP(6), INTERVAL 30 DAY), 1, NULL, FROM_BASE64(''), 'image/jpeg', UTC_TIMESTAMP(6))
ON DUPLICATE KEY UPDATE
  Title=VALUES(Title), Description=VALUES(Description), EndsAt=VALUES(EndsAt),
  ImageData=VALUES(ImageData), ImageContentType=VALUES(ImageContentType), IsActive=1;

